import{_ as t,o,c as a,a2 as s}from"./chunks/framework.CNDaxUod.js";const u=JSON.parse('{"title":"Google Chat setup","description":"","frontmatter":{},"headers":[],"relativePath":"guide/google-chat-setup.md","filePath":"guide/google-chat-setup.md"}'),n={name:"guide/google-chat-setup.md"};function i(r,e,l,c,d,h){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="google-chat-setup" tabindex="-1">Google Chat setup <a class="header-anchor" href="#google-chat-setup" aria-label="Permalink to &quot;Google Chat setup&quot;">​</a></h1><p>One-time setup to connect the bot to your Google Workspace. You need to be a Workspace admin (for domain-wide install) and have a Google Cloud project.</p><h2 id="_1-create-a-gcp-project-and-enable-the-chat-api" tabindex="-1">1. Create a GCP project and enable the Chat API <a class="header-anchor" href="#_1-create-a-gcp-project-and-enable-the-chat-api" aria-label="Permalink to &quot;1. Create a GCP project and enable the Chat API&quot;">​</a></h2><ol><li>Go to <a href="https://console.cloud.google.com" target="_blank" rel="noreferrer">console.cloud.google.com</a> and create a project (e.g. <code>asyncup</code>).</li><li>Note the <strong>project number</strong> (Dashboard → Project info) — you&#39;ll paste it into AsyncUp&#39;s settings.</li><li>Enable the API: <strong>APIs &amp; Services → Library → Google Chat API → Enable</strong>.</li></ol><h2 id="_2-create-a-service-account" tabindex="-1">2. Create a service account <a class="header-anchor" href="#_2-create-a-service-account" aria-label="Permalink to &quot;2. Create a service account&quot;">​</a></h2><ol><li><strong>IAM &amp; Admin → Service Accounts → Create service account</strong> (e.g. <code>asyncup</code>). No project roles are needed — Chat API access comes from the app configuration.</li><li>Open the account → <strong>Keys → Add key → JSON</strong> and download the key file. You&#39;ll paste its contents into the dashboard in step 3 — no file mounting.</li></ol><h2 id="_3-deploy-the-bot-and-connect-it" tabindex="-1">3. Deploy the bot and connect it <a class="header-anchor" href="#_3-deploy-the-bot-and-connect-it" aria-label="Permalink to &quot;3. Deploy the bot and connect it&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># set DASHBOARD_TOKEN (any long random string)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># set SECRET_KEY      (openssl rand -hex 32)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>Expose it over <strong>public HTTPS</strong> behind your reverse proxy (Caddy/nginx/Traefik) or, for a quick test, a tunnel like <code>cloudflared tunnel --url http://localhost:8080</code>. Your event URL is <code>https://&lt;your-host&gt;/chat/events</code>.</p><p>Then open <code>https://&lt;your-host&gt;/app</code>, sign in with <code>DASHBOARD_TOKEN</code> → <strong>Settings → Google Chat</strong> and paste:</p><ul><li>the <strong>project number</strong> from step 1</li><li>the <strong>service-account key JSON</strong> from step 2 (stored encrypted)</li></ul><p>Changes apply immediately — no restart. (On Cloud Run you can skip the key and use the service&#39;s own identity via Application Default Credentials.)</p><h2 id="_4-configure-the-chat-app" tabindex="-1">4. Configure the Chat app <a class="header-anchor" href="#_4-configure-the-chat-app" aria-label="Permalink to &quot;4. Configure the Chat app&quot;">​</a></h2><p><strong>APIs &amp; Services → Google Chat API → Configuration</strong> tab:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>App name</td><td><code>AsyncUp</code> (or your pick)</td></tr><tr><td>Avatar URL</td><td><code>https://asyncup-dev.github.io/asyncup/logo-256.png</code> (the AsyncUp logo, or any 256×256 PNG)</td></tr><tr><td>Description</td><td><code>Async daily standups</code></td></tr><tr><td>Functionality</td><td>✅ Receive 1:1 messages, ✅ Join spaces and group conversations</td></tr><tr><td>Connection settings</td><td><strong>HTTP endpoint URL</strong> → <code>https://&lt;your-host&gt;/chat/events</code></td></tr><tr><td>Authentication Audience</td><td><strong>Project Number</strong> (recommended — this is what AsyncUp verifies)</td></tr><tr><td>Visibility</td><td>the people/Google Group who&#39;ll use it (see below)</td></tr></tbody></table><blockquote><p>Today&#39;s console may default to <strong>&quot;Build this Chat app as a Google Workspace add-on.&quot;</strong> That&#39;s fine — HTTP-endpoint Chat apps work either way. Just note the add-on path needs the same distribution steps below.</p></blockquote><p>Save. The app status should become <strong>LIVE</strong>. Paste the <strong>project number</strong> into the dashboard&#39;s <strong>Audience</strong> field (Settings → Google Chat) so it matches the Authentication Audience you set here.</p><h2 id="_5-get-the-bot-to-your-team" tabindex="-1">5. Get the bot to your team <a class="header-anchor" href="#_5-get-the-bot-to-your-team" aria-label="Permalink to &quot;5. Get the bot to your team&quot;">​</a></h2><p>How users actually receive the bot — allowlist + self-add (small teams) vs a private Marketplace listing + admin install (org-wide, zero-touch) — is its own topic. <strong>See <a href="./distribution.html">Installing AsyncUp for your team</a>.</strong></p><blockquote><p>The bot can only DM users it shares a DM space with. Admin install creates that automatically; otherwise each user must add the app once themselves.</p></blockquote><h2 id="_6-create-your-first-standup" tabindex="-1">6. Create your first standup <a class="header-anchor" href="#_6-create-your-first-standup" aria-label="Permalink to &quot;6. Create your first standup&quot;">​</a></h2><ol><li>Create (or open) the space where reports should land.</li><li>Add the bot to the space (<code>+ Add people &amp; apps</code>).</li><li>Mention it:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@AsyncUp setup Engineering</span></span>
<span class="line"><span>@AsyncUp add @Alice @Bob</span></span>
<span class="line"><span>@AsyncUp status</span></span></code></pre></div><p>Prompts go out at the configured time the next working day. 🎉</p><h2 id="calendar-ooo" tabindex="-1">Optional: Calendar OOO sync <a class="header-anchor" href="#calendar-ooo" aria-label="Permalink to &quot;Optional: Calendar OOO sync {#calendar-ooo}&quot;">​</a></h2><p>To auto-mark people as away when their Google Calendar has an <em>Out of office</em> event, the service account needs <strong>domain-wide delegation</strong>:</p><ol><li><strong>IAM &amp; Admin → Service Accounts → your account</strong> → copy the <strong>OAuth 2 Client ID</strong> (a long number).</li><li><a href="https://admin.google.com" target="_blank" rel="noreferrer">admin.google.com</a> → <strong>Security → Access and data control → API controls → Domain-wide delegation → Add new</strong>: <ul><li>Client ID: the number from step 1</li><li>Scopes (comma-separated): <code>https://www.googleapis.com/auth/calendar.events.readonly, https://www.googleapis.com/auth/admin.directory.user.readonly</code></li></ul></li><li>Enable the <strong>Google Calendar API</strong> and <strong>Admin SDK API</strong> in your GCP project.</li><li>Dashboard → <strong>Settings → Workspace</strong> → tick <em>Google Calendar OOO sync</em> and set the <strong>Workspace admin email</strong>.</li></ol><p>With the admin email set, AsyncUp resolves each person&#39;s email through the Directory API (Directory reads must impersonate an admin), so OOO sync works even for people who never interacted with the bot. Without it, emails are learned the first time each person uses the bot. People who are OOO are listed as 🏖️ away — never as missing.</p><p>The <code>admin.directory.user.readonly</code> scope is read-only. If you skip it and leave the admin email empty, everything else works unchanged.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li><strong>&quot;No DM space with users/…&quot;</strong> in logs → that user doesn&#39;t have the app installed; see step 5.</li><li><strong>401 on events</strong> → the value in Settings → Google Chat must be the project <em>number</em>, not the project ID.</li><li><strong>No prompts arriving</strong> → check <code>docker compose logs</code>; the scheduler logs every run open/close. Verify the standup <code>status</code>, days, and timezone.</li><li><strong>Replies not threading</strong> → the bot posts with <code>threadKey</code>, which threads correctly even if the parent message failed; check the space&#39;s history settings.</li></ul>`,31)])])}const g=t(n,[["render",i]]);export{u as __pageData,g as default};
